func (v QueueValue) Equal(o attr.Value) bool {
	other, ok := o.(QueueValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Aqm.Equal(other.Aqm) {
		return false
	}

	if !v.Buckets.Equal(other.Buckets) {
		return false
	}

	if !v.Description.Equal(other.Description) {
		return false
	}

	if !v.Ecn.Equal(other.Ecn) {
		return false
	}

	if !v.Enabled.Equal(other.Enabled) {
		return false
	}

	if !v.Mask.Equal(other.Mask) {
		return false
	}

	if !v.Maskbits.Equal(other.Maskbits) {
		return false
	}

	if !v.Maskbitsv6.Equal(other.Maskbitsv6) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	if !v.Number.Equal(other.Number) {
		return false
	}

	if !v.ParamCodelInterval.Equal(other.ParamCodelInterval) {
		return false
	}

	if !v.ParamCodelTarget.Equal(other.ParamCodelTarget) {
		return false
	}

	if !v.ParamGredMaxP.Equal(other.ParamGredMaxP) {
		return false
	}

	if !v.ParamGredMaxTh.Equal(other.ParamGredMaxTh) {
		return false
	}

	if !v.ParamGredMinTh.Equal(other.ParamGredMinTh) {
		return false
	}

	if !v.ParamGredWQ.Equal(other.ParamGredWQ) {
		return false
	}

	if !v.ParamPieAlpha.Equal(other.ParamPieAlpha) {
		return false
	}

	if !v.ParamPieBeta.Equal(other.ParamPieBeta) {
		return false
	}

	if !v.ParamPieMaxBurst.Equal(other.ParamPieMaxBurst) {
		return false
	}

	if !v.ParamPieMaxEcnth.Equal(other.ParamPieMaxEcnth) {
		return false
	}

	if !v.ParamPieTarget.Equal(other.ParamPieTarget) {
		return false
	}

	if !v.ParamPieTupdate.Equal(other.ParamPieTupdate) {
		return false
	}

	if !v.ParamRedMaxP.Equal(other.ParamRedMaxP) {
		return false
	}

	if !v.ParamRedMaxTh.Equal(other.ParamRedMaxTh) {
		return false
	}

	if !v.ParamRedMinTh.Equal(other.ParamRedMinTh) {
		return false
	}

	if !v.ParamRedWQ.Equal(other.ParamRedWQ) {
		return false
	}

	if !v.PieCapdrop.Equal(other.PieCapdrop) {
		return false
	}

	if !v.PieOnoff.Equal(other.PieOnoff) {
		return false
	}

	if !v.PiePderand.Equal(other.PiePderand) {
		return false
	}

	if !v.PieQdelay.Equal(other.PieQdelay) {
		return false
	}

	if !v.Plr.Equal(other.Plr) {
		return false
	}

	if !v.Qlimit.Equal(other.Qlimit) {
		return false
	}

	if !v.Weight.Equal(other.Weight) {
		return false
	}

	return true
}

